<script module lang="ts">
/**
 * Boolean (or indeterminate) choice (`design/components/checkbox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/checkbox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/checkbox'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  agentMember,
  joinSlot,
  normalizeProps,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/checkbox.module.css'

export type CheckedState = boolean | 'indeterminate'

export interface CheckboxProps {
  'aria-describedby'?: string
  'aria-label'?: string
  /**
   * The id of a label elsewhere on the page, such as `SettingsRow`'s one label for a whole row.
   */
  'aria-labelledby'?: string
  'aria-required'?: boolean
  checked?: boolean | 'indeterminate'
  defaultChecked?: boolean | 'indeterminate'
  disabled?: boolean
  id?: string
  /**
   * Usually set by FormField.
   */
  invalid?: boolean
  /**
   * Visible inline label. Omit it only where the context labels the box, and then `aria-label`
   * is required.
   */
  label?: string
  name?: string
  onCheckedChange?: (checked: CheckedState) => void
  value?: string
}

export const controlKind = 'row-labelled'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  checked,
  defaultChecked,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  label: labelOwn,
  name,
  onCheckedChange,
  value,
}: CheckboxProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, label: labelOwn, name: name }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let box = $state<HTMLElement | null>(null)
const documentDirection = useDirection(() => box)
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      checked: checked,
      defaultChecked: defaultChecked,
      disabled: disabled,
      invalid: invalid,
      required: ariaRequired,
      name: name,
      value: value,
      onCheckedChange: (details) => {
        onCheckedChange?.(details.checked)
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const dataState = $derived(
  api.indeterminate ? 'indeterminate' : api.checked ? 'checked' : 'unchecked',
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'Checkbox',
    element: () => box,
    state: () => ({ checked: api.indeterminate ? 'mixed' : api.checked, disabled: disabled }),
    actions: { check: () => api.setChecked(true), uncheck: () => api.setChecked(false) },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if label === undefined
    }<button
      bind:this={box}
      class={styles.box}
      type="button"
      role="checkbox"
      {id}
      aria-checked={api.indeterminate ? 'mixed' : api.checked}
      {disabled}
      aria-label={ariaLabel}
      aria-labelledby={ariaLabelledby}
      aria-describedby={ariaDescribedby}
      aria-required={ariaRequired}
      aria-invalid={(invalid) ? true : undefined}
      data-state={dataState}
      data-disabled={(disabled) ? '' : undefined}
      data-required={(ariaRequired) ? '' : undefined}
      data-invalid={(invalid) ? '' : undefined}
      data-member="checkbox"
      onclick={() => { api.toggleChecked() }}
      onkeydown={(event) => { if (event.key === 'Enter') event.preventDefault() }}
      >{#if api.checked || api.indeterminate
        }<span class={styles.indicator} data-state={dataState}
          ><Icon name={api.indeterminate ? 'indeterminate' : 'confirm'} size="sm"
        /></span
      >{/if
    }</button
  >{:else
    }<label
      class={styles.row}
      data-state={dataState}
      data-disabled={(disabled) ? '' : undefined}
      data-invalid={(invalid) ? '' : undefined}
      data-required={(ariaRequired) ? '' : undefined}
      data-member="checkbox"
      ><button
        bind:this={box}
        class={styles.box}
        type="button"
        role="checkbox"
        {id}
        aria-checked={api.indeterminate ? 'mixed' : api.checked}
        {disabled}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledby}
        aria-describedby={ariaDescribedby}
        aria-required={ariaRequired}
        aria-invalid={(invalid) ? true : undefined}
        data-state={dataState}
        data-disabled={(disabled) ? '' : undefined}
        data-required={(ariaRequired) ? '' : undefined}
        data-invalid={(invalid) ? '' : undefined}
        data-member="checkbox"
        onclick={() => { api.toggleChecked() }}
        onkeydown={(event) => { if (event.key === 'Enter') event.preventDefault() }}
        >{#if api.checked || api.indeterminate
          }<span class={styles.indicator} data-state={dataState}
            ><Icon name={api.indeterminate ? 'indeterminate' : 'confirm'} size="sm"
          /></span
        >{/if
      }</button
      ><span class={styles.label}>{label}</span
    ></label
  >{/if
  }{#if name !== undefined && api.checked}<input type="hidden" {name} value={value ?? 'on'} />{/if
}{/if
}{@render joined.end?.()}
